{
  "schemaVersion": "0.2",
  "slug": "sheet",
  "name": "Sheet",
  "status": "experimental",
  "purpose": "Presents a modal panel anchored to an edge of the viewport.",
  "scenarios": [
    "Show a confirmation sheet",
    "Show a bottom action sheet",
    "Show a side sheet"
  ],
  "props": {
    "triggerLabel": {
      "type": "string",
      "required": true,
      "description": "Trigger button label."
    },
    "title": {
      "type": "string",
      "required": true,
      "description": "Sheet title."
    },
    "children": {
      "type": "node",
      "required": false,
      "description": "Sheet content."
    },
    "closeLabel": {
      "type": "string",
      "required": true,
      "description": "Close button label."
    },
    "position": {
      "type": "enum",
      "required": false,
      "description": "Edge anchor.",
      "values": [
        "start",
        "end",
        "bottom"
      ],
      "default": "bottom"
    },
    "open": {
      "type": "boolean",
      "required": false,
      "description": "Controlled open state."
    },
    "onOpenChange": {
      "type": "event",
      "required": false,
      "description": "Called when open state changes."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "position",
      "values": [
        "start",
        "end",
        "bottom"
      ],
      "default": "bottom",
      "description": "Edge anchor."
    }
  ],
  "states": [
    {
      "name": "open",
      "description": "Sheet is visible."
    },
    {
      "name": "closed",
      "description": "Sheet is hidden."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page"
    ],
    "allowedChildren": [
      "text",
      "button",
      "form"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not open multiple sheets.",
    "Do not use for primary workflows."
  ],
  "a11y": {
    "role": "dialog",
    "keyboard": [
      "Tab cycles inside",
      "Escape closes"
    ],
    "focus": "Focus moves inside on open and returns on close.",
    "labeling": "Title labels the sheet.",
    "wcag": [
      "2.4.3",
      "2.1.1"
    ]
  },
  "responsive": {
    "strategy": "Bottom sheet on compact; side sheet on larger viewports.",
    "breakpoints": {
      "compact": "Bottom sheet.",
      "medium": "Positioned sheet.",
      "large": "Positioned sheet."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only; start/end refer to inline edges.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "sheet",
    "states": [
      "open",
      "closed"
    ],
    "intents": [
      "present-overlay"
    ]
  }
}

.cu-sheet {
  display: flex;
  flex-direction: column;
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
}

.cu-sheet--start {
  margin-inline-end: auto;
  max-inline-size: 24rem;
  block-size: 100%;
  inline-size: 100%;
}

.cu-sheet--end {
  margin-inline-start: auto;
  max-inline-size: 24rem;
  block-size: 100%;
  inline-size: 100%;
}

.cu-sheet--bottom {
  margin-block-start: auto;
  max-block-size: 50vh;
  inline-size: 100%;
  border-start-start-radius: var(--cu-radius-lg);
  border-start-end-radius: var(--cu-radius-lg);
  box-shadow: var(--cu-shadow-lg);
}

.cu-sheet__backdrop {
  position: fixed;
  inset: 0;
  background: color-mix(in srgb, var(--cu-color-background-inverse) 40%, transparent);
  backdrop-filter: blur(var(--cu-blur-surface));
  -webkit-backdrop-filter: blur(var(--cu-blur-surface));
}

.cu-sheet__title {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 700;
}

.cu-sheet__body {
  flex: 1;
  overflow: auto;
  margin-block: var(--cu-space-3);
}

.cu-sheet__close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-block-size: 2.75rem;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  font: inherit;
  cursor: pointer;
}
